"""Inflected forms of Greek names, generated by rule from the dictionary form.

The gazetteer lists each name once. A name in a sentence appears in the genitive,
accusative or vocative, and a surname also in its feminine form, so the matcher needs all
of them. Accents are ignored when matching, which is why a moved accent is not generated.
"""

from enum import StrEnum

from gateway.app.core.textnorm import fold, latin_key


class NameKind(StrEnum):
    GIVEN_MALE = "given-names-male"
    GIVEN_FEMALE = "given-names-female"
    SURNAME = "surnames"


# Folded ending of the dictionary form, and the endings that replace it.
_MASCULINE = (
    ("οσ", ("οσ", "ου", "ο", "ε")),
    ("ησ", ("ησ", "η")),
    ("ασ", ("ασ", "α")),
    ("εσ", ("εσ", "ε")),
    ("ων", ("ων", "ωνα", "ωνοσ", "ωνασ")),
)
_FEMININE = (
    ("α", ("α", "ασ")),
    ("η", ("η", "ησ")),
    ("ω", ("ω", "ωσ")),
)
# Surnames in -ίδης and -άδης form the feminine in -ου, the rest of -ης in -η.
_PATRONYMIC = ("ιδησ", "αδησ")


def _swap(folded: str, rules: tuple[tuple[str, tuple[str, ...]], ...]) -> set[str]:
    for ending, replacements in rules:
        if folded.endswith(ending) and len(folded) > len(ending) + 1:
            stem = folded[: -len(ending)]
            return {stem + replacement for replacement in replacements}
    return {folded}


def name_forms(name: str, kind: NameKind) -> set[str]:
    """Every case form of `name`, folded (lower-case, no accents, final sigma as sigma)."""
    folded = fold(name)
    if kind is NameKind.GIVEN_FEMALE:
        return _swap(folded, _FEMININE)
    if kind is NameKind.GIVEN_MALE:
        return _swap(folded, _MASCULINE)
    forms = _swap(folded, _MASCULINE)
    if forms == {folded}:
        return _swap(folded, _FEMININE)
    if folded.endswith(_PATRONYMIC):
        forms.add(folded[:-2] + "ου")
    return forms


def name_keys(name: str, kind: NameKind) -> set[str]:
    """The forms as script-independent keys, so "Παπαδοπούλου" and "Papadopoulou" agree."""
    return {latin_key(form) for form in name_forms(name, kind)}
